"""Add-on entry point.

No provider request is made until a validated local profile exists.  This keeps
the bridge from guessing an undocumented provider API or ever invoking control.
"""

from __future__ import annotations

import json
import logging
import os
import time
import threading
import secrets
from pathlib import Path
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .profile import ProfileError, load_profile
from .bridge import Bridge
from .provider import Client, ProviderError
from .restream import Go2Rtc

LOG = logging.getLogger("md_parking_bridge")


class State:
    def __init__(self) -> None:
        self.started_at = time.time()
        self.profile_error: str | None = None
        self.bridge: Bridge | None = None
        try:
            load_profile()
        except ProfileError as exc:
            self.profile_error = str(exc)

    def start(self) -> None:
        try:
            options=json.loads(Path('/data/options.json').read_text())
            required=('provider_username','provider_object_id','provider_sms_code','app','client_id','fingerprint')
            if not all(options.get(key) for key in required): return
            client=Client(options.get('auth_url','https://auth.mdparking.ru/v2/base'),options['app'],options['client_id'],options['fingerprint'])
            bridge=Bridge(client,Go2Rtc(),int(options.get('refresh_before_expiry_seconds',45)))
            bridge.authenticate(options['provider_username'],options['provider_object_id'],options['provider_sms_code'])
            bridge.discover(); bridge.refresh_due(); self.bridge=bridge; self.profile_error=None
            def loop():
                while True:
                    try: bridge.refresh_due()
                    except ProviderError: LOG.exception('stream refresh failed')
                    time.sleep(5)
            threading.Thread(target=loop,daemon=True).start()
        except Exception as exc:
            self.profile_error='bridge initialization failed'; LOG.exception('bridge initialization failed')

    def diagnostics(self) -> dict[str, object]:
        return {
            "read_only": True,
            "provider_profile": "ready" if self.profile_error is None else "not_ready",
            "restream": "not_started" if self.profile_error else "pending",
            "uptime_seconds": int(time.time() - self.started_at),
            "last_refresh": None,
            "last_failure": self.profile_error,
            "camera_count": len(self.bridge.cameras) if self.bridge else 0,
        }


def make_handler(state: State, api_token: str):
    class Handler(BaseHTTPRequestHandler):
        def do_POST(self) -> None:  # noqa: N802
            if self.path != '/v1/pair' or not state.pairing_enabled or state.paired:
                LOG.warning('pairing request rejected: enabled=%s paired=%s', state.pairing_enabled, state.paired)
                self.send_error(HTTPStatus.NOT_FOUND); return
            state.paired = True
            LOG.info('one-time pairing completed')
            body=json.dumps({'api_token': api_token}).encode()
            self.send_response(HTTPStatus.OK); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
        def do_GET(self) -> None:  # noqa: N802
            if self.path not in {"/health", "/diagnostics", "/v1/cameras"}:
                self.send_error(HTTPStatus.NOT_FOUND)
                return
            if self.path != '/health' and (not api_token or self.headers.get("Authorization") != f"Bearer {api_token}"):
                self.send_error(HTTPStatus.UNAUTHORIZED)
                return
            payload={'status':'ok'} if self.path == '/health' else (state.diagnostics() if self.path != '/v1/cameras' else {'cameras':[{'id':camera.checkpoint_id,'name':camera.name,'stream_name':camera.stream_name} for camera in (state.bridge.cameras.values() if state.bridge else [])]})
            body = json.dumps(payload).encode("utf-8")
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            LOG.info("status_api %s", format % args)

    return Handler


def main() -> None:
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(name)s: %(message)s")
    token = os.environ.get("API_TOKEN", "")
    token_path=Path('/data/bridge_api_token')
    if not token:
        token=token_path.read_text().strip() if token_path.exists() else secrets.token_urlsafe(32)
        if not token_path.exists(): token_path.write_text(token)
    state = State()
    try: state.pairing_enabled=bool(json.loads(Path('/data/options.json').read_text()).get('pairing_enabled',False))
    except Exception: state.pairing_enabled=False
    state.paired=False
    state.start()
    if state.profile_error:
        LOG.warning("provider profile is not ready: %s", state.profile_error)
    server = ThreadingHTTPServer(("0.0.0.0", 8099), make_handler(state, token))
    LOG.info("read-only status API listening on port 8099")
    server.serve_forever()


if __name__ == "__main__":
    main()
